// src/lib/gas-api.ts
var GasInputSchema = exports_external.object({
  chain_set: exports_external.array(exports_external.string()).min(1, "At least one chain required"),
  calldata_size_bytes: exports_external.number().positive("Calldata size must be positive"),
  gas_units_est: exports_external.number().positive("Gas units must be positive")
});
var GasRouteSchema = exports_external.object({
  chain: exports_external.string(),
  fee_native: exports_external.number(),
  fee_usd: exports_external.number(),
  busy_level: exports_external.enum(["low", "medium", "high", "congested"]),
  tip_hint_gwei: exports_external.number()
});
var GasResponseSchema = exports_external.object({
  recommended_chain: exports_external.string(),
  routes: exports_external.array(GasRouteSchema)
});
var MOCK_GAS_DATA = {
  ethereum: {
    base_fee_gwei: 25,
    tip_gwei: 2,
    eth_usd: 3200
  },
  base: {
    base_fee_gwei: 0.5,
    tip_gwei: 0.1,
    eth_usd: 3200
  },
  arbitrum: {
    base_fee_gwei: 0.1,
    tip_gwei: 0.01,
    eth_usd: 3200
  },
  optimism: {
    base_fee_gwei: 0.2,
    tip_gwei: 0.05,
    eth_usd: 3200
  },
  polygon: {
    base_fee_gwei: 30,
    tip_gwei: 20,
    eth_usd: 3200
  }
};
async function getGasRoutes(chain_set, calldata_size_bytes, gas_units_est) {
  const routes = [];
  for (const chain of chain_set) {
    const chainData = MOCK_GAS_DATA[chain.toLowerCase()];
    if (!chainData)
      continue;
    const calldata_overhead = Math.ceil(calldata_size_bytes / 32) * 16;
    const total_gas = gas_units_est + calldata_overhead;
    const base_fee = chainData.base_fee_gwei;
    const tip = chainData.tip_gwei;
    const eth_price = chainData.eth_usd;
    const fee_eth = (base_fee + tip) * total_gas * 0.000000001;
    const fee_usd = fee_eth * eth_price;
    let busy_level = "low";
    if (base_fee > 50)
      busy_level = "congested";
    else if (base_fee > 20)
      busy_level = "high";
    else if (base_fee > 5)
      busy_level = "medium";
    routes.push({
      chain,
      fee_native: fee_eth,
      fee_usd: parseFloat(fee_usd.toFixed(2)),
      busy_level,
      tip_hint_gwei: tip
    });
  }
  routes.sort((a, b) => a.fee_usd - b.fee_usd);
  return routes;
}

